import java.io.InputStream;
import java.io.OutputStream;
import java.io.IOException;

public class Main {

    static class FenwickTree {
        int n;
        long[] tree;

        FenwickTree(int n) {
            this.n = n;
            this.tree = new long[n + 2];
        }

        void add(int i, long delta) {
            for (; i <= n; i += i & -i) {
                tree[i] += delta;
            }
        }

        long query(int i) {
            long sum = 0;
            for (; i > 0; i -= i & -i) {
                sum += tree[i];
            }
            return sum;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner in = new FastScanner(System.in);
        FastOutput out = new FastOutput(System.out);

        int n = in.nextInt();
        int m = in.nextInt();

        // Duas BITs para cobrir o tamanho N + 2
        FenwickTree bitA = new FenwickTree(n + 2);
        FenwickTree bitB = new FenwickTree(n + 2);

        for (int k = 0; k < m; k++) {
            int type = in.nextInt();
            if (type == 1) {
                int i = in.nextInt();
                long v = in.nextLong();
                int l = i;
                int r = (int) Math.min((long) n, i + v - 1);
                long a = v + i;
                long b = -1;

                bitA.add(l, a);
                bitA.add(r + 1, -a);

                bitB.add(l, b);
                bitB.add(r + 1, -b);
            } else if (type == 2) {
                int i = in.nextInt();
                long v = in.nextLong();
                int l = (int) Math.max(1L, i - v + 1);
                int r = i;
                long a = v - i;
                long b = 1;

                bitA.add(l, a);
                bitA.add(r + 1, -a);

                bitB.add(l, b);
                bitB.add(r + 1, -b);
            } else {
                int i = in.nextInt();
                long ans = bitA.query(i) + (long) i * bitB.query(i);
                out.println(ans);
            }
        }

        out.flush();
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[32768];
        private int head = 0;
        private int tail = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (head >= tail) {
                head = 0;
                tail = in.read(buffer, 0, buffer.length);
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        int nextInt() throws IOException {
            int c = read();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = read();
            }
            int res = 0;
            while (c > ' ') {
                if (c < '0' || c > '9') {
                    c = read();
                    continue;
                }
                res = res * 10 + c - '0';
                c = read();
            }
            return res;
        }

        long nextLong() throws IOException {
            int c = read();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = read();
            }
            long res = 0;
            while (c > ' ') {
                if (c < '0' || c > '9') {
                    c = read();
                    continue;
                }
                res = res * 10 + c - '0';
                c = read();
            }
            return res;
        }
    }

    static class FastOutput {
        private final OutputStream out;
        private final byte[] buffer = new byte[32768];
        private int count = 0;

        FastOutput(OutputStream out) {
            this.out = out;
        }

        private void write(byte b) throws IOException {
            if (count >= buffer.length) {
                flush();
            }
            buffer[count++] = b;
        }

        void println(long val) throws IOException {
            if (val == 0) {
                write((byte) '0');
                write((byte) '\n');
                return;
            }
            if (val < 0) {
                write((byte) '-');
                val = -val;
            }
            byte[] digits = new byte[20];
            int len = 0;
            while (val > 0) {
                digits[len++] = (byte) ('0' + (val % 10));
                val /= 10;
            }
            while (len > 0) {
                write(digits[--len]);
            }
            write((byte) '\n');
        }

        void flush() throws IOException {
            if (count > 0) {
                out.write(buffer, 0, count);
                count = 0;
            }
        }
    }
}
